#### 55\. 跳跃游戏
(https://leetcode.cn/problems/jump-game/) 本质是模拟题+单指针遍历
```cpp
class Solution {
public:
    bool canJump(vector<int>& nums) {
        int point = 0;
        int maxone = nums[point];
        while (point < nums.size() - 1 && point < maxone) {
            maxone = max(point + 1 + nums[point + 1], maxone);
            point += 1;
        }
        if (maxone < nums.size() - 1) return false;
        else return true;
    }
};
// for循环优化
class Solution {
public:
    bool canJump(vector<int>& nums) {
        int maxone = nums[0];
        for (int i = 0;i < nums.size() - 1 && i < maxone; i++) {
            maxone = max(i + 1 + nums[i + 1], maxone);
        }
        return maxone < nums.size() - 1 ? false : true;
    }
};
```
![[Pasted image 20250716143325.png]] 倒序做法：
```cpp
class Solution {
    public bool canJump(int[] nums) {
        int lastPos = nums.length - 1;
        for (int i = lastPos; i >= 0; i--) {
            if (i + nums[i] >= lastPos) {
                lastPos = i;
            }
        }
        return lastPos == 0;
    }
}
```

